const named = (pads, names) => { pads.forEach((p, i) => { if (names[i] !== undefined) p.name = names[i]; }); return pads; };
const fnOf = names => { const f = {}; for (const n of names) { const a = autoFunc(n); if (a) f[n] = a; } return f; };
function hdrRow(n, pitch, names, d = 1.7, drill = 1.0, y = 0) { return (names || [...Array(n)].map((_, i) => String(i + 1))).map((nm, i) => tht(i + 1, -(n - 1) * pitch / 2 + i * pitch, y, { sq: i === 0, d, drill, name: nm, func: autoFunc(nm) })); }

