function qfnFP(n, body, pitch, ep) {
  const pads = qfpPads(n, pitch, body - 0.1, 0.8, pitch * 0.55);
  pads.push(smd(n + 1, 0, 0, ep, ep, { name: "EP" }));
  return addFP({ id: `qfn${n}_${body}`, name: `QFN-${n} ${body}x${body}mm (${pitch}mm)`, cat: IC, prefix: "U", value: `QFN-${n}`, desc: "No-lead package with thermal pad (EP, usually GND). Hard to hand-solder — use hot air", tags: "qfn smd ic thermal pad", verify: true, pads, body: { x: 0, y: 0, w: body, h: body, col: "#1a1a1a", notch: true }, silk: "none" });
}
